.xforms * { font-family: 돋움체;}
.xforms_title * { font-size: 13pt; padding : 0 0 10 0;}

.xforms table {
font-size: 10px;
padding:0px;
border-collapse:collapse;
color: #3D3D3D;
}
.xforms td {
padding-left:0px;
padding-top:0px;
border-collapse:collapse;
